package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.persistence.PostgresBackupVersionRepository.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.mock.web.*;
import java.time.Instant;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
/** Synthetic HTTP-boundary objects only; no DB, storage, KMS or real permissions. */
class BackupVersionInventoryControllerTest {
 static final String ACTOR="69000000-0000-4000-8000-000000000001",TENANT="69000000-0000-4000-8000-000000000002",ASSET="69000000-0000-4000-8000-000000000003",RUN="69000000-0000-4000-8000-000000000004";
 static final Instant AT=Instant.parse("2026-10-21T00:00:00.123Z");
 PlatformRepository platform;ObjectProvider<BackupVersionInventoryQuery> provider;BackupVersionInventoryQuery query;BackupVersionInventoryController controller;
 @SuppressWarnings("unchecked") @BeforeEach void setup(){platform=mock(PlatformRepository.class);provider=mock(ObjectProvider.class);query=mock(BackupVersionInventoryQuery.class);when(provider.getIfUnique()).thenReturn(query);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(member(7)));when(query.inventory(any(),any(),any(),anyInt())).thenReturn(new InventoryPage(List.of(),false,null));controller=new BackupVersionInventoryController(platform,provider);}
 static Membership member(long version){return new Membership(ACTOR,TENANT,"padmin",version,true,List.of("assets:read"));}
 static UUID id(int n){return UUID.fromString("69000000-0000-4000-8000-"+String.format("%012x",n));}
 static InventoryItem item(int n){return new InventoryItem(id(n),UUID.fromString(ASSET),UUID.fromString(RUN),1,2,AT.minusSeconds(1),AT,"a".repeat(64),300);}
 static InventoryScope scope(){return new InventoryScope(UUID.fromString(TENANT),UUID.fromString(ASSET));}
 static Access access(){return new Access(UUID.fromString(TENANT),UUID.fromString(ACTOR),7);}
 MockHttpServletRequest request(){var r=new MockHttpServletRequest("GET","/api/v1/assets/"+ASSET+"/backup-versions");r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);r.setAttribute("mop.trace_id","synthetic-inventory");return r;}
 @SuppressWarnings("unchecked") static Map<String,Object> data(Object value){return(Map<String,Object>)((Map<?,?>)value).get("data");}
 @Test void scopesComeFromCurrentSessionAndNoResultDoesNotGrantAnything(){var result=data(controller.list(ASSET,request()));assertEquals(TENANT,result.get("tenant_id"));assertEquals(ACTOR,result.get("actor_id"));assertEquals(ASSET,result.get("asset_id"));assertEquals(7L,result.get("accepted_permission_version"));assertEquals(List.of(),result.get("items"));assertNull(result.get("total_count"));for(String key:List.of("download_authorized","device_execution_authorized","current_object_health_verified","object_storage_accessed","retention_verified","recovery_verified"))assertEquals(false,result.get(key));verify(query).inventory(access(),scope(),null,15);verify(platform,times(2)).membership(ACTOR,TENANT);}
 @Test void unconfiguredAuthorityReturnsUnavailableNotEmptySuccess(){when(provider.getIfUnique()).thenReturn(null);var e=assertThrows(DomainException.class,()->controller.list(ASSET,request()));assertEquals(503,e.status);assertEquals("BACKUP_VERSION_INVENTORY_NOT_CONFIGURED",e.code);verifyNoInteractions(query);}
 @Test void invalidSessionAndMembershipRejectBeforeService(){var missing=request();missing.setUserPrincipal(null);assertEquals(401,assertThrows(DomainException.class,()->controller.list(ASSET,missing)).status);var bad=request();bad.getSession().setAttribute("mop.tenant_id",42);assertEquals(401,assertThrows(DomainException.class,()->controller.list(ASSET,bad)).status);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.empty());assertEquals(401,assertThrows(DomainException.class,()->controller.list(ASSET,request())).status);verifyNoInteractions(query);}
 @Test void draftPermissionDoesNotSubstituteForAssetVisibilityOrEnumeration(){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"padmin",7,true,List.of("backup_plan_drafts:read"))));assertEquals(403,assertThrows(DomainException.class,()->controller.list(ASSET,request())).status);verifyNoInteractions(query);}
 @Test void administratorStillNeedsExplicitDeviceEnumerationAuthority(){when(query.inventory(any(),any(),any(),anyInt())).thenThrow(new DomainException(403,"INTERNAL_DENIAL","SYNTHETIC_PRIVATE_DETAIL"));var e=assertThrows(DomainException.class,()->controller.list(ASSET,request()));assertEquals(403,e.status);assertEquals("BACKUP_VERSION_INVENTORY_ACCESS_DENIED",e.code);assertFalse(e.getMessage().contains("SYNTHETIC"));}
 @Test void pairedCursorIsCanonicalAndBoundToSessionTenantAndPathAsset(){var r=request();r.addParameter("page_size","50");r.addParameter("before_registered_at",AT.toString());r.addParameter("before_version_id",id(30).toString());controller.list(ASSET,r);verify(query).inventory(access(),scope(),new InventoryCursor(scope(),AT,id(30)),50);}
 @Test void eachUnpairedCursorIsRejected(){for(String key:List.of("before_registered_at","before_version_id")){var r=request();r.addParameter(key,key.equals("before_registered_at")?AT.toString():id(30).toString());assertEquals(400,assertThrows(DomainException.class,()->controller.list(ASSET,r)).status);}verifyNoInteractions(query);}
 @Test void invalidPageSizesAreNotCoercedOrTruncated(){for(String value:List.of("0","51","01","1.0","1e1","-1"," 1","99999999")){var r=request();r.addParameter("page_size",value);assertEquals(400,assertThrows(DomainException.class,()->controller.list(ASSET,r)).status);}verifyNoInteractions(query);}
 @Test void invalidOrNormalizedTimesAreRejected(){for(String value:List.of("0000-01-01T00:00:00Z","2026-02-30T00:00:00Z","2026-10-21T24:00:00Z","2026-10-21T00:00:60Z","2026-10-21T00:00:00.0001Z","2026-10-21T00:00:00+00:00","2026-10-21 00:00:00Z")){var r=request();r.addParameter("before_registered_at",value);r.addParameter("before_version_id",id(30).toString());assertEquals(400,assertThrows(DomainException.class,()->controller.list(ASSET,r)).status);}verifyNoInteractions(query);}
 @Test void duplicateAndForgedQueryFieldsNeverReachService(){for(String key:List.of("tenant_id","actor_id","download","key_reference","page")){var r=request();r.addParameter(key,"forged");assertEquals(400,assertThrows(DomainException.class,()->controller.list(ASSET,r)).status);}var r=request();r.addParameter("page_size","10","20");assertThrows(DomainException.class,()->controller.list(ASSET,r));verifyNoInteractions(query);}
 @Test void oversizedEncodedQueryIsRejected(){var r=request();r.setQueryString("x".repeat(2049));assertThrows(DomainException.class,()->controller.list(ASSET,r));verifyNoInteractions(query);}
 @Test void sameMillisecondUuidOrderingUsesCanonicalUnsignedTextOrder(){var high=new InventoryItem(UUID.fromString("f9000000-0000-4000-8000-000000000001"),UUID.fromString(ASSET),UUID.fromString(RUN),1,2,AT.minusSeconds(1),AT,"a".repeat(64),300);var low=item(10);var next=new InventoryCursor(scope(),AT,low.versionId());var out=BackupVersionInventoryController.pageDto(access(),scope(),null,2,new InventoryPage(List.of(high,low),true,next));assertEquals(low.versionId().toString(),out.get("next_before_version_id"));}
 @Test void duplicateWrongOrderAndCrossAssetRowsRejectWholePage(){var a=item(10);var b=item(20);var foreign=new InventoryItem(a.versionId(),id(90),a.runId(),a.attemptNumber(),a.completedRunVersion(),a.objectObservedAt(),a.registeredAt(),a.encryptedSha256(),a.encryptedBytes());for(var items:List.of(List.of(a,a),List.of(a,b),List.of(foreign))){when(query.inventory(any(),any(),any(),anyInt())).thenReturn(new InventoryPage(items,false,null));assertEquals(503,assertThrows(DomainException.class,()->controller.list(ASSET,request())).status);}}
 @Test void lookaheadCursorMustMatchLastVisibleItemAndScope(){var a=item(10);for(var next:List.of(new InventoryCursor(scope(),AT,id(11)),new InventoryCursor(new InventoryScope(id(99),scope().assetId()),AT,a.versionId()),new InventoryCursor(scope(),AT.plusMillis(1),a.versionId()))){assertThrows(DomainException.class,()->BackupVersionInventoryController.pageDto(access(),scope(),null,1,new InventoryPage(List.of(a),true,next)));}assertThrows(DomainException.class,()->BackupVersionInventoryController.pageDto(access(),scope(),null,2,new InventoryPage(List.of(a),true,new InventoryCursor(scope(),AT,a.versionId()))));}
 @Test void rowOutsideRequestedBoundaryIsRejected(){var a=item(10);assertThrows(DomainException.class,()->BackupVersionInventoryController.pageDto(access(),scope(),new InventoryCursor(scope(),AT,a.versionId()),15,new InventoryPage(List.of(a),false,null)));}
 @Test void invalidSummaryTimeHashBytesAndAttemptAreNotExposed(){var a=item(10);for(var bad:List.of(new InventoryItem(a.versionId(),a.assetId(),a.runId(),0,2,a.objectObservedAt(),AT,a.encryptedSha256(),300),new InventoryItem(a.versionId(),a.assetId(),a.runId(),1,1,a.objectObservedAt(),AT,a.encryptedSha256(),300),new InventoryItem(a.versionId(),a.assetId(),a.runId(),1,2,AT.plusSeconds(1),AT,a.encryptedSha256(),300),new InventoryItem(a.versionId(),a.assetId(),a.runId(),1,2,a.objectObservedAt(),AT.plusNanos(1),a.encryptedSha256(),300),new InventoryItem(a.versionId(),a.assetId(),a.runId(),1,2,a.objectObservedAt(),AT,"not-a-hash",300),new InventoryItem(a.versionId(),a.assetId(),a.runId(),1,2,a.objectObservedAt(),AT,a.encryptedSha256(),246))){assertThrows(DomainException.class,()->BackupVersionInventoryController.pageDto(access(),scope(),null,15,new InventoryPage(List.of(bad),false,null)));}}
 @Test void completionMetadataIsExplicitAndNoInternalReferencesAreSerialized(){when(query.inventory(any(),any(),any(),anyInt())).thenReturn(new InventoryPage(List.of(item(10)),false,null));var result=data(controller.list(ASSET,request()));var row=(Map<?,?>)((List<?>)result.get("items")).get(0);assertEquals(15,row.size());assertEquals(true,row.get("registration_and_run_completion_recorded"));for(String key:List.of("key_reference","object_key","bucket","download_url","registered_by","trace_id","execution_reference","lease_owner"))assertFalse(row.containsKey(key));}
 @Test void membershipRevocationAfterReadSuppressesOtherwiseValidPage(){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(member(7)),Optional.of(member(8)));assertEquals(401,assertThrows(DomainException.class,()->controller.list(ASSET,request())).status);}
 @Test void capabilityFactsChangeEvenAtSameVersionInvalidateTheResponse(){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(member(7)),Optional.of(new Membership(ACTOR,TENANT,"padmin",7,true,List.of("assets:read","audit:read"))));assertEquals(401,assertThrows(DomainException.class,()->controller.list(ASSET,request())).status);}
 @Test void changedSessionTenantCannotReuseOldReadResult(){var r=request();when(query.inventory(any(),any(),any(),anyInt())).thenAnswer(call->{r.getSession().setAttribute("mop.tenant_id",id(91).toString());return new InventoryPage(List.of(),false,null);});assertEquals(401,assertThrows(DomainException.class,()->controller.list(ASSET,r)).status);}
 @Test void unavailableServiceAndPrivateExceptionsNeverLeakDetails(){when(query.inventory(any(),any(),any(),anyInt())).thenThrow(new IllegalStateException("SYNTHETIC_PRIVATE_DETAIL"));var e=assertThrows(DomainException.class,()->controller.list(ASSET,request()));assertEquals(503,e.status);assertFalse(e.getMessage().contains("SYNTHETIC"));assertNull(e.getCause());}
 @Test void nonemptyPageWithoutMoreCannotReturnACursor(){assertThrows(DomainException.class,()->BackupVersionInventoryController.pageDto(access(),scope(),null,15,new InventoryPage(List.of(item(10)),false,new InventoryCursor(scope(),AT,id(10)))));}
 @Test void privateHeadersAreSet(){var response=new MockHttpServletResponse();controller.privateHeaders(response);assertEquals("no-store",response.getHeader("Cache-Control"));assertEquals("no-referrer",response.getHeader("Referrer-Policy"));}
 @Test void postgresBindingRequiresBothIndependentAuthorities(){assertThrows(NullPointerException.class,()->BackupVersionInventoryQuery.postgres(mock(javax.sql.DataSource.class),null,(c,a,s)->{}));assertThrows(NullPointerException.class,()->BackupVersionInventoryQuery.postgres(mock(javax.sql.DataSource.class),(c,a,s,o)->{},null));}
 @Test void aRealEmptyBeanProviderFailsClosedWithoutMockedAvailability(){var beans=new org.springframework.beans.factory.support.DefaultListableBeanFactory();var c=new BackupVersionInventoryController(platform,beans.getBeanProvider(BackupVersionInventoryQuery.class));assertEquals("BACKUP_VERSION_INVENTORY_NOT_CONFIGURED",assertThrows(DomainException.class,()->c.list(ASSET,request())).code);}
 @Test void ambiguousBindingsDoNotSelectAnArbitraryAuthority(){var beans=new org.springframework.beans.factory.support.DefaultListableBeanFactory();beans.registerSingleton("first",query);beans.registerSingleton("second",mock(BackupVersionInventoryQuery.class));var c=new BackupVersionInventoryController(platform,beans.getBeanProvider(BackupVersionInventoryQuery.class));assertEquals(503,assertThrows(DomainException.class,()->c.list(ASSET,request())).status);verifyNoInteractions(query);}

 @Test void membershipDependencyFailureIsSanitizedBeforeAnyQuery(){when(platform.membership(ACTOR,TENANT)).thenThrow(new DomainException(503,"PRIVATE_DRIVER","SYNTHETIC_PRIVATE_DETAIL"));var e=assertThrows(DomainException.class,()->controller.list(ASSET,request()));assertEquals(503,e.status);assertFalse(e.getMessage().contains("SYNTHETIC"));verifyNoInteractions(query);}

}
